def collect_targets(
    self, targets: Optional["TargetType"], onerror: Optional[Callable[[str, Exception], None]] = None, **kwargs: Any
) -> list["StageInfo"]:
    from dvc.repo.stage import StageInfo
    from dvc.utils.collections import ensure_list

    targets = ensure_list(targets)
    if not targets:
        return [StageInfo(stage) for stage in self.stages]
    targets_hash = self._hash_targets(targets, **kwargs)
    if targets_hash not in self._collected_targets:
        result = []
        for target in targets:
            try:
                result.extend(self.repo.stage.collect_granular(target, **kwargs))
            except Exception as exc:
                if onerror:
                    onerror(target, exc)
                else:
                    raise
        self._collected_targets[targets_hash] = result
    return self._collected_targets[targets_hash]

